  e.state = 'move'; const ox = e.x, oy = e.y; tryMove(e, (e.inv.x - e.x) / d * dt * e.d.speed * 0.7, (e.inv.y - e.y) / d * dt * e.d.speed * 0.7, 0.28); e.mvx = e.x - ox; e.mvy = e.y - oy; e.t += dt;
