  if (solid(p.x, p.y) || p.life <= 0 || p.z <= 0.05) { p.dead = true; const x = p.x - p.vx * dt, y = p.y - p.vy * dt; play('stone_land', 0.6, 1, { x, y }); hearNoise(x, y, 7); spawnPuff(x, y, 2); }
