const v28PortalHint = p => p.v28.blood ? `PORTAL → ${V28_BLOOD.name} · FLER FIENDER, MER BELÖNING` : `PORTAL → UTMANING: ${V28_RULES[p.v28.chal].name} · +${v28Reward() + 20} GULD`;
