    if (pr.hp20 <= 0) { v20Wreck(pr); play('ratnest', 0.55, 0.8, { x: pr.x, y: pr.y }); spawnPuff(pr.x, pr.y, 10); stat('ratnests'); say('RÅTTBOET ÄR FÖRSTÖRT', 1.2); }
